DROP TABLE IF EXISTS `resumen_transacciones_diarias`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `resumen_transacciones_diarias` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `fecha` date NOT NULL,
  `cantidad_transacciones` int NOT NULL,
  `cantidad_debitos` int NOT NULL,
  `cantidad_creditos` int NOT NULL,
  `monto_total_debitos` decimal(15,2) NOT NULL,
  `monto_total_creditos` decimal(15,2) NOT NULL,
  `cantidad_anomalias` int NOT NULL,
  `archivo_origen` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `fecha_generacion` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_resumen_fecha_archivo` (`fecha`,`archivo_origen`)
) ENGINE=InnoDB AUTO_INCREMENT=268 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
